function notify(text){$('toast').textContent=text;toastTime=5;$('toast').style.opacity=1}function targetsUI(){$('targets').innerHTML=survivors.map((s,i)=>`<div class="target ${s.saved?'done':''}"><span class="num">0${i+1}</span><div>${s.name}<small>${s.area} · ${s.clues}/4 条线索</small></div><span class="status">${s.saved?'✓ 已获救':'● 待搜救'}</span></div>`).join('')}
